17	package org.springframework.samples.petclinic.rest.controller.v1;
18	
19	import java.util.Collection;
20	import java.util.List;
21	
22	import org.springframework.http.HttpHeaders;
23	import org.springframework.http.HttpStatus;
24	import org.springframework.http.ResponseEntity;
25	import org.springframework.samples.petclinic.mapper.OwnerMapper;
26	import org.springframework.samples.petclinic.mapper.PetMapper;
27	import org.springframework.samples.petclinic.mapper.VisitMapper;
28	import org.springframework.samples.petclinic.model.Owner;
29	import org.springframework.samples.petclinic.model.Pet;
30	import org.springframework.samples.petclinic.model.Visit;
31	import org.springframework.samples.petclinic.rest.api.OwnersApi;
32	import org.springframework.samples.petclinic.rest.controller.OwnerRegistrar;
33	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
34	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
35	import org.springframework.samples.petclinic.rest.dto.PetDto;
36	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
37	import org.springframework.samples.petclinic.rest.dto.VisitDto;
38	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
39	import org.springframework.samples.petclinic.service.ClinicService;
40	import org.springframework.security.access.prepost.PreAuthorize;
41	import org.springframework.web.bind.annotation.CrossOrigin;
42	import org.springframework.web.bind.annotation.RequestMapping;
43	import org.springframework.web.bind.annotation.RestController;
44	import org.springframework.web.util.UriComponentsBuilder;
45	
46	import jakarta.servlet.http.HttpServletRequest;
47	import jakarta.transaction.Transactional;
48	
49	/**
50	 * @author Vitaliy Fedoriv
51	 */
52	
53	@RestController
54	@CrossOrigin(exposedHeaders = "errors, content-type")
55	@RequestMapping("/api")
56	public class OwnerRestControllerV1 implements OwnersApi {
57	
58	    private final ClinicService clinicService;
59	
60	    private final OwnerMapper ownerMapper;
61	
62	    private final PetMapper petMapper;
63	
64	    private final VisitMapper visitMapper;
65	
66	    private final OwnerRegistrar ownerRegistrar;
67	
68	    private final HttpServletRequest request;
69	
70	    public OwnerRestControllerV1(ClinicService clinicService,
71	                                 OwnerMapper ownerMapper,
72	                                 PetMapper petMapper,
73	                                 VisitMapper visitMapper,
74	                                 OwnerRegistrar ownerRegistrar,
75	                                 HttpServletRequest request) {
76	        this.clinicService = clinicService;
77	        this.ownerMapper = ownerMapper;
78	        this.petMapper = petMapper;
79	        this.visitMapper = visitMapper;
80	        this.ownerRegistrar = ownerRegistrar;
81	        this.request = request;
82	    }
83	
84	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
85	    @Override
86	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
87	        Collection<Owner> owners;
88	        if (lastName != null) {
89	            owners = this.clinicService.findOwnerByLastName(lastName);
90	        } else {
91	            owners = this.clinicService.findAllOwners();
92	        }
93	        if (owners.isEmpty()) {
94	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
95	        }
96	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
97	    }
98	
99	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
100	    @Override
101	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
102	        Owner owner = this.clinicService.findOwnerById(ownerId);
103	        if (owner == null) {
104	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
105	        }
106	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
107	    }
108	
109	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
110	    @Override
111	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
112	        return ownerRegistrar.register(ownerFieldsDto, request.getHeader("Idempotency-Key"));
113	    }
114	
115	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
116	    @Override
117	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
118	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
119	        if (currentOwner == null) {
120	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
121	        }
122	        currentOwner.setAddress(ownerFieldsDto.getAddress());
123	        currentOwner.setCity(ownerFieldsDto.getCity());
124	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
125	        currentOwner.setLastName(ownerFieldsDto.getLastName());
126	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
127	        this.clinicService.saveOwner(currentOwner);
128	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
129	    }
130	
131	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
132	    @Transactional
133	    @Override
134	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
135	        Owner owner = this.clinicService.findOwnerById(ownerId);
136	        if (owner == null) {
137	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
138	        }
139	        // Soft-delete: flag the owner deleted and retain the row rather than removing it, so it
140	        // is still readable via GET while being ignored by the create duplicate/identity checks.
141	        owner.setDeleted(true);
142	        this.clinicService.saveOwner(owner);
143	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
144	    }
145	
146	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
147	    @Override
148	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
149	        Owner owner = this.clinicService.findOwnerById(ownerId);
150	        if (owner == null) {
151	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
152	        }
153	        HttpHeaders headers = new HttpHeaders();
154	        Pet pet = petMapper.toPet(petFieldsDto);
155	        owner.setId(ownerId);
156	        pet.setOwner(owner);
157	        pet.getType().setName(null);
158	        this.clinicService.savePet(pet);
159	        PetDto petDto = petMapper.toPetDto(pet);
160	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
161	            .buildAndExpand(pet.getId()).toUri());
162	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
163	    }
164	
165	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
166	    @Override
167	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
168	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
169	        if (currentOwner != null) {
170	            Pet currentPet = this.clinicService.findPetById(petId);
171	            if (currentPet != null) {
172	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
173	                currentPet.setName(petFieldsDto.getName());
174	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
175	                this.clinicService.savePet(currentPet);
176	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
177	            }
178	        }
179	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
180	    }
181	
182	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
183	    @Override
184	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
185	        HttpHeaders headers = new HttpHeaders();
186	        Visit visit = visitMapper.toVisit(visitFieldsDto);
187	        Pet pet = new Pet();
188	        pet.setId(petId);
189	        visit.setPet(pet);
190	        this.clinicService.saveVisit(visit);
191	        VisitDto visitDto = visitMapper.toVisitDto(visit);
192	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
193	            .buildAndExpand(visit.getId()).toUri());
194	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
195	    }
196	
197	
198	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
199	    @Override
200	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
201	        Owner owner = this.clinicService.findOwnerById(ownerId);
202	        if (owner != null) {
203	            Pet pet = owner.getPet(petId);
204	            if (pet != null) {
205	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
206	            }
207	        }
208	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
209	    }
210	}
