318	     * @param candidate the fully-normalized owner about to be created
319	     * @return the matching existing owner's id, or {@code null} if the candidate is no soft match
320	     */
321	    private Integer possibleDuplicateOf(Owner candidate) {
322	        String postcode = candidate.getPostcode();
323	        if (postcode == null) {
324	            return null;
325	        }
326	        String lastNameKey = IdentityUtils.normalizeIdentity(candidate.getLastName());
327	        return this.clinicService.findAllOwners().stream()
328	            .filter(existing -> !existing.isDeleted()
329	                && IdentityUtils.normalizeIdentity(existing.getLastName()).equals(lastNameKey)
330	                && postcode.equals(existing.getPostcode())
331	                && !postcode.isBlank()
332	                && !java.util.Objects.equals(candidate.getTelephone(), existing.getTelephone()))
