339	    /**
340	     * Build the customer code assigned to {@code owner} on create, formatted
341	     * {@code '<REGION>-<HASH8>'}: REGION is the region code derived from the owner's postcode
342	     * (falling back to the city) via {@link CityRegionResolver}, and HASH8 is the first eight
343	     * upper-case hex characters of the SHA-256 digest of the normalized telephone concatenated
344	     * with the last name (e.g. 'NSW-1A2B3C4D'). There is no per-city sequence.
345	     *
346	     * <p>When the computed code collides with an already-registered owner's customerCode it is
347	     * de-duplicated by appending {@code '-<n>'} with the smallest {@code n} of 2 or more that
348	     * makes it unique (e.g. 'NSW-1A2B3C4D-2'), and the unique code is returned.
349	     */
350	    private String customerCode(Owner owner) {
351	        String region = cityRegionResolver.regionFor(owner.getCity(), owner.getPostcode());
352	        String hash8 = HashUtils.sha256HexPrefix(owner.getTelephone() + owner.getLastName(), 8);
353	        String base = region + "-" + hash8;
354	        java.util.Set<String> existing = this.clinicService.findAllOwners().stream()
355	            .map(Owner::getCustomerCode)
356	            .filter(java.util.Objects::nonNull)
357	            .collect(java.util.stream.Collectors.toSet());
358	        if (!existing.contains(base)) {
359	            return base;
360	        }
361	        int n = 2;
362	        while (existing.contains(base + "-" + n)) {
363	            n++;
364	        }
365	        return base + "-" + n;
366	    }
