381	    /** Fixed list of public holidays that a registration date must roll past. */
382	    private static final Set<LocalDate> PUBLIC_HOLIDAYS = Set.of(
383	        LocalDate.of(2026, 1, 1),
384	        LocalDate.of(2026, 1, 26),
385	        LocalDate.of(2026, 4, 25),
386	        LocalDate.of(2026, 12, 25),
387	        LocalDate.of(2026, 12, 28));
388	
389	    /**
390	     * Roll a registration date forward to the next business day: a Saturday, Sunday
391	     * or listed public holiday advances one day at a time until it lands on a weekday
392	     * that is not a public holiday. A plain weekday is returned unchanged.
393	     */
394	    private static LocalDate toBusinessDay(LocalDate date) {
395	        while (isWeekend(date) || PUBLIC_HOLIDAYS.contains(date)) {
396	            date = date.plusDays(1);
397	        }
398	        return date;
399	    }
400	
401	    private static boolean isWeekend(LocalDate date) {
402	        return switch (date.getDayOfWeek()) {
403	            case SATURDAY, SUNDAY -> true;
404	            default -> false;
405	        };
406	    }
407	
408	    /**
409	     * Build the membership number assigned on create, formatted
410	     * {@code '<customerCode>-M<YY>'} where YY is the last two digits of the fiscal year of the
411	     * business-day-adjusted {@code registrationDate} (the fiscal year starts on 1 July), e.g.
412	     * 'NSW-1A2B3C4D-M26'.
413	     */
414	    private static String membershipNumber(String customerCode, LocalDate registrationDate) {
415	        String yy = String.format("%02d", OwnerMapper.fiscalYear(registrationDate) % 100);
416	        return customerCode + "-M" + yy;
417	    }
