17	package org.springframework.samples.petclinic.rest.controller;
18	
19	import java.util.Map;
20	
21	import org.springframework.stereotype.Component;
22	
23	/**
24	 * Normalises a raw telephone number to the single canonical form under which it is both
25	 * stored and compared for duplicates.
26	 *
27	 * <p>Keeping this in one place means the stored form and the form used to detect duplicate
28	 * telephones can never drift apart: an owner is a duplicate of another exactly when their
29	 * telephones normalise to the same value.
30	 *
31	 * <p>The canonical form is E.164: a leading '+' followed by 8 to 15 digits. A number that
32	 * already carries a leading '+' keeps its explicit country code; otherwise country code
33	 * '+61' is assumed and a single leading '0' is dropped from the national digits. Spaces,
34	 * dashes and brackets are stripped. Anything that cannot reduce to a '+' plus 8 to 15 digits
35	 * has no canonical form.
36	 */
37	@Component
38	public class TelephoneNormalizer {
39	
40	    private static final String DEFAULT_COUNTRY_CODE = "61";
41	
42	    private static final int MIN_DIGITS = 8;
43	
44	    private static final int MAX_DIGITS = 15;
45	
46	    /**
47	     * Country code (the digits after the '+') to the exact number of national digits an
48	     * E.164 telephone for that country must carry. Australia ('+61') requires 9 national
49	     * digits and the North American Numbering Plan ('+1') requires 10. A country code not
50	     * listed here carries no per-country length constraint beyond the generic E.164 range.
51	     */
52	    private static final Map<String, Integer> NATIONAL_NUMBER_LENGTHS = Map.of("61", 9, "1", 10);
53	
54	    /**
55	     * Reduce a raw telephone to its canonical E.164 stored form.
56	     *
57	     * @param rawTelephone the telephone as supplied by the client, possibly {@code null} or
58	     *                     containing spaces, dashes or brackets
59	     * @return the canonical E.164 telephone (a '+' followed by 8 to 15 digits), or
60	     *         {@code null} if {@code rawTelephone} cannot form a valid E.164 number
61	     */
62	    public String normalize(String rawTelephone) {
63	        if (rawTelephone == null) {
64	            return null;
65	        }
66	        String trimmed = rawTelephone.trim();
67	        boolean hasCountryCode = trimmed.startsWith("+");
68	        String digits = trimmed.replaceAll("\\D", "");
69	        if (!hasCountryCode) {
70	            if (digits.startsWith("0")) {
71	                digits = digits.substring(1);
72	            }
73	            digits = DEFAULT_COUNTRY_CODE + digits;
74	        }
75	        if (digits.length() < MIN_DIGITS || digits.length() > MAX_DIGITS) {
76	            return null;
77	        }
78	        return "+" + digits;
79	    }
80	
81	    /**
82	     * Whether a canonical E.164 telephone carries the national-number length its country
83	     * code requires. Country code '+61' requires 9 national digits and '+1' requires 10;
84	     * the national number is the digits that follow the country code. A number whose
85	     * country code has no pinned length is not constrained beyond the generic E.164 range.
86	     *
87	     * @param e164Telephone a canonical E.164 telephone (a '+' followed by digits), as
88	     *                      produced by {@link #normalize(String)}
89	     * @return {@code true} if the national-number length matches the country code (or the
90	     *         country code has no pinned length), {@code false} otherwise
91	     */
92	    public boolean hasValidNationalNumberLength(String e164Telephone) {
93	        if (e164Telephone == null || !e164Telephone.startsWith("+")) {
94	            return false;
95	        }
96	        String countryCode = countryCodeOf(e164Telephone);
97	        if (countryCode == null) {
98	            return true;
99	        }
100	        return nationalNumberOf(e164Telephone, countryCode).length() == NATIONAL_NUMBER_LENGTHS.get(countryCode);
101	    }
102	
103	    /**
104	     * Format a canonical E.164 telephone for humans: a '+' and the country code, a space, then the
105	     * national digits grouped in threes from the left (e.g. '+61412345678' becomes
106	     * '+61 412 345 678'). A number whose country code is not listed carries no known split into
107	     * country code and national number and is returned unchanged.
108	     *
109	     * @param e164Telephone a canonical E.164 telephone (a '+' followed by digits), as produced by
110	     *                      {@link #normalize(String)}
111	     * @return the human-readable telephone, or {@code null} when {@code e164Telephone} is
112	     *         {@code null} or not a '+'-prefixed number
113	     */
114	    public String toDisplayForm(String e164Telephone) {
115	        if (e164Telephone == null || !e164Telephone.startsWith("+")) {
116	            return null;
117	        }
118	        String countryCode = countryCodeOf(e164Telephone);
119	        if (countryCode == null) {
120	            return e164Telephone;
121	        }
122	        return "+" + countryCode + " " + groupInThrees(nationalNumberOf(e164Telephone, countryCode));
123	    }
124	
125	    /**
126	     * Group a run of digits into space-separated groups of three, from the left, with any final
127	     * short group left as-is (e.g. '412345678' becomes '412 345 678').
128	     */
129	    private static String groupInThrees(String digits) {
130	        StringBuilder grouped = new StringBuilder(digits.length() + digits.length() / 3);
131	        for (int i = 0; i < digits.length(); i++) {
132	            if (i > 0 && i % 3 == 0) {
133	                grouped.append(' ');
134	            }
135	            grouped.append(digits.charAt(i));
136	        }
137	        return grouped.toString();
138	    }
139	
140	    /**
141	     * The listed country code (a key of {@link #NATIONAL_NUMBER_LENGTHS}) that a canonical E.164
142	     * telephone carries, i.e. the one its digits begin with, or {@code null} when the number's
143	     * digits begin with no listed country code.
144	     *
145	     * @param e164Telephone a canonical E.164 telephone (a '+' followed by digits), as produced by
146	     *                      {@link #normalize(String)}
147	     * @return the listed country code the number begins with, or {@code null} when none is listed
148	     */
149	    private static String countryCodeOf(String e164Telephone) {
150	        String digits = e164Telephone.substring(1);
151	        for (String countryCode : NATIONAL_NUMBER_LENGTHS.keySet()) {
152	            if (digits.startsWith(countryCode)) {
153	                return countryCode;
154	            }
155	        }
156	        return null;
157	    }
158	
159	    /**
160	     * The national number of a canonical E.164 telephone: the digits that follow the '+' and the
161	     * given country code.
162	     *
163	     * @param e164Telephone a canonical E.164 telephone (a '+' followed by digits)
164	     * @param countryCode   the country code the number carries, as returned by
165	     *                      {@link #countryCodeOf(String)}
166	     * @return the national-number digits (the digits after the country code)
167	     */
168	    private static String nationalNumberOf(String e164Telephone, String countryCode) {
169	        return e164Telephone.substring(1 + countryCode.length());
170	    }
171	}
